from AlgorithmImports import *
from collections import deque


class ExactStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = deque(maxlen=100)
        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.rsi_period = 14
        self.rsi_previous_close = None
        self.rsi_gain_sum = 0.0
        self.rsi_loss_sum = 0.0
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.rsi_samples = 0
        self.aapl_rsi = None

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_pending = False
        self.aapl_pending = False
        self.pending_orders = {}

        self.spy_investment_percentage = 1.0

    def OnData(self, data):
        available = {}
        for symbol in self.symbols:
            if symbol in data.Bars:
                available[symbol] = data.Bars[symbol]

        self._update_market_state(available)

        if len(available) != len(self.symbols):
            return

        if len(self.spy_closes) < 100 or self.aapl_rsi is None:
            return

        spy_bar = available[self.spy]
        aapl_bar = available[self.aapl]

        spy_sma = sum(self.spy_closes) / 100.0
        spy_crossed_above = (
            self.spy_previous_close is not None
            and self.spy_previous_sma is not None
            and self.spy_previous_close <= self.spy_previous_sma
            and spy_bar.Close > spy_sma
        )
        spy_crossed_below = (
            self.spy_previous_close is not None
            and self.spy_previous_sma is not None
            and self.spy_previous_close >= self.spy_previous_sma
            and spy_bar.Close < spy_sma
        )

        aapl_buy_reason = self.aapl_red_streak >= 3
        aapl_sell_reason = self.aapl_rsi > 60.0

        if self.spy_lot > 0 and not self.spy_pending and spy_crossed_below:
            self._submit_sell(self.spy, self.spy_lot, "Strategy A liquidation")

        if self.aapl_lot > 0 and not self.aapl_pending and aapl_sell_reason:
            self._submit_sell(self.aapl, self.aapl_lot, "Strategy B liquidation")

        if self.spy_lot == 0 and not self.spy_pending and spy_crossed_above:
            quantity = int(
                (self.Portfolio.TotalPortfolioValue *
                 self.spy_investment_percentage) / spy_bar.Close
            )
            if quantity > 0:
                self._submit_buy(self.spy, quantity, "Strategy A buy")

        if self.aapl_lot == 0 and not self.aapl_pending and aapl_buy_reason:
            if self.Portfolio.Cash >= 20000.0:
                quantity = int(20000.0 / aapl_bar.Close)
                if quantity > 0:
                    self._submit_buy(self.aapl, quantity, "Strategy B buy")

    def _update_market_state(self, bars):
        if self.spy in bars:
            close = float(bars[self.spy].Close)

            previous_sma = None
            if len(self.spy_closes) == 100:
                previous_sma = sum(self.spy_closes) / 100.0

            self.spy_closes.append(close)
            self.spy_previous_sma = previous_sma
            self.spy_previous_close = close

        if self.aapl in bars:
            close = float(bars[self.aapl].Close)

            if self.aapl_previous_close is not None:
                if close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

                change = close - self.aapl_previous_close
                gain = max(change, 0.0)
                loss = max(-change, 0.0)

                if self.rsi_samples < self.rsi_period:
                    self.rsi_gain_sum += gain
                    self.rsi_loss_sum += loss
                    self.rsi_samples += 1

                    if self.rsi_samples == self.rsi_period:
                        self.rsi_average_gain = (
                            self.rsi_gain_sum / self.rsi_period
                        )
                        self.rsi_average_loss = (
                            self.rsi_loss_sum / self.rsi_period
                        )
                else:
                    self.rsi_average_gain = (
                        (self.rsi_average_gain * (self.rsi_period - 1)) + gain
                    ) / self.rsi_period
                    self.rsi_average_loss = (
                        (self.rsi_average_loss * (self.rsi_period - 1)) + loss
                    ) / self.rsi_period

                if self.rsi_average_gain is not None:
                    if self.rsi_average_loss == 0:
                        self.aapl_rsi = 100.0
                    else:
                        relative_strength = (
                            self.rsi_average_gain / self.rsi_average_loss
                        )
                        self.aapl_rsi = (
                            100.0 - (100.0 / (1.0 + relative_strength))
                        )

            self.aapl_previous_close = close

    def _submit_buy(self, symbol, quantity, tag):
        ticket = self.MarketOnCloseOrder(symbol, quantity, tag)
        self.pending_orders[ticket.OrderId] = ("buy", symbol)
        if symbol == self.spy:
            self.spy_pending = True
        elif symbol == self.aapl:
            self.aapl_pending = True

    def _submit_sell(self, symbol, quantity, tag):
        ticket = self.MarketOnCloseOrder(symbol, -quantity, tag)
        self.pending_orders[ticket.OrderId] = ("sell", symbol)
        if symbol == self.spy:
            self.spy_pending = True
        elif symbol == self.aapl:
            self.aapl_pending = True

    def OnOrderEvent(self, order_event):
        if order_event.OrderId not in self.pending_orders:
            return

        action, symbol = self.pending_orders[order_event.OrderId]

        if order_event.Status == OrderStatus.Filled:
            filled = abs(int(order_event.FillQuantity))

            if symbol == self.spy:
                if action == "buy":
                    self.spy_lot += filled
                else:
                    self.spy_lot = max(0, self.spy_lot - filled)
                self.spy_pending = False

            elif symbol == self.aapl:
                if action == "buy":
                    self.aapl_lot += filled
                else:
                    self.aapl_lot = max(0, self.aapl_lot - filled)
                self.aapl_pending = False

            del self.pending_orders[order_event.OrderId]

        elif order_event.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.PartiallyFilled
        ):
            if order_event.Status != OrderStatus.PartiallyFilled:
                if symbol == self.spy:
                    self.spy_pending = False
                elif symbol == self.aapl:
                    self.aapl_pending = False
                del self.pending_orders[order_event.OrderId]
